const body = $input.first().json.body || $input.first().json;
const title = body.title || '';
const slug = body.slug || '';
const summary = (body.summary || body.excerpt || '').substring(0, 200);
const rating = body.rating || '';
const price = body.price || '';
const featuredImage = body.featuredImage || '';
const affiliateUrl = body.affiliateUrl || '';

const articleUrl = 'https://kaoshop-omega.vercel.app/article/' + slug;

// Facebook message
let fbText = '\ud83d\uded2 ' + title + '\n\n';
if (summary) fbText += summary + '...\n\n';
if (rating) fbText += '\u2b50 \u0e04\u0e30\u0e41\u0e19\u0e19: ' + rating + '/5\n';
if (price) fbText += '\ud83d\udcb0 \u0e23\u0e32\u0e04\u0e32: \u0e3f' + Number(price).toLocaleString('th-TH') + '\n';
fbText += '\n\ud83d\udcd6 \u0e2d\u0e48\u0e32\u0e19\u0e23\u0e35\u0e27\u0e34\u0e27\u0e40\u0e15\u0e47\u0e21: ' + articleUrl;
if (affiliateUrl) fbText += '\n\ud83d\udecd \u0e0b\u0e37\u0e49\u0e2d\u0e2a\u0e34\u0e19\u0e04\u0e49\u0e32: ' + affiliateUrl;

// Line OA Flex Message payload
const heroImage = featuredImage || 'https://placehold.co/800x520/FF6B00/ffffff?text=KaoShop';
const linePayload = {
  messages: [
    {
      type: 'flex',
      altText: '\ud83d\udccc \u0e1a\u0e17\u0e04\u0e27\u0e32\u0e21\u0e43\u0e2b\u0e21\u0e48: ' + title,
      contents: {
        type: 'bubble',
        hero: {
          type: 'image',
          url: heroImage,
          size: 'full',
          aspectRatio: '20:13',
          aspectMode: 'cover',
          action: { type: 'uri', uri: articleUrl }
        },
        body: {
          type: 'box',
          layout: 'vertical',
          contents: [
            {
              type: 'text',
              text: '\ud83c\udd95 \u0e1a\u0e17\u0e04\u0e27\u0e32\u0e21\u0e43\u0e2b\u0e21\u0e48!',
              weight: 'bold',
              color: '#1DB446',
              size: 'sm'
            },
            {
              type: 'text',
              text: title,
              weight: 'bold',
              size: 'xl',
              margin: 'md',
              wrap: true
            },
            rating ? {
              type: 'text',
              text: '\u2b50 ' + rating + '/5',
              size: 'sm',
              color: '#aaaaaa',
              margin: 'md'
            } : null,
            summary ? {
              type: 'text',
              text: summary + '...',
              size: 'sm',
              color: '#555555',
              margin: 'md',
              wrap: true
            } : null
          ].filter(Boolean)
        },
        footer: {
          type: 'box',
          layout: 'vertical',
          spacing: 'sm',
          contents: [
            {
              type: 'button',
              style: 'primary',
              height: 'sm',
              color: '#FF6B00',
              action: { type: 'uri', label: '\ud83d\udcd6 \u0e2d\u0e48\u0e32\u0e19\u0e23\u0e35\u0e27\u0e34\u0e27', uri: articleUrl }
            },
            affiliateUrl ? {
              type: 'button',
              style: 'secondary',
              height: 'sm',
              action: { type: 'uri', label: '\ud83d\udecd \u0e0b\u0e37\u0e49\u0e2d\u0e40\u0e25\u0e22', uri: affiliateUrl }
            } : null
          ].filter(Boolean)
        }
      }
    }
  ]
};

return [{
  json: {
    title,
    slug,
    articleUrl,
    featuredImage,
    affiliateUrl,
    fbText,
    linePayload
  }
}];
